import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(17))
G.add_edges_from([(0,15), (3,15), (6,15), (9,15), (11,15), (14,16)])
for i in range(17):
    for j in range(i+1, 17):
        if (i, j) not in G.edges and (j, i) not in G.edges:
            G.add_edge(i, j)
            if len(list(nx.find_cycle(G))) > 0:
                G.remove_edge(i, j)
print(G.edges)
